/**
 * Audited. The value is never cached. The audit event is committed before the value leaves, so when the registry, the audit log or the store does not answer, the request gets 503 with `Retry-After` and no value is sent. More reveals than the limit in a minute get 429 with `Retry-After`.
 * @summary Reveal a masked value
 */
export const revealValue = async (id: string,
    revealRequest: RevealRequest, options?: Parameters<typeof apiFetch>[1]): Promise<RevealedValue> => {

    const getHeaders = (h?: NonNullable<RequestInit['headers']>): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(h as Iterable<Iterable<string>>, (entry) => Array.from(entry) as [string, string]),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<string | readonly string[] | undefined>(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
return apiFetch<RevealedValue>(getRevealValueUrl(id),
  {
    ...options,
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...getHeaders(options?.headers) },
    body: JSON.stringify(revealRequest)
  }
);}





